/** Compute Entrypoint Contract
  *
  * guarantee BRAKE_FACT_DERIVATION
  * @param api_brake_observation incoming data port
  * @param api_brake_to_authorization outgoing data port
  * @param api_brake_to_lifecycle outgoing data port
  */
pub fn compute_spec_BRAKE_FACT_DERIVATION_guarantee(
  api_brake_observation: Vehicle_Start_Readiness_Recovery_Supervisor::BrakeObservation,
  api_brake_to_authorization: Vehicle_Start_Readiness_Recovery_Supervisor::BrakeFacts,
  api_brake_to_lifecycle: Vehicle_Start_Readiness_Recovery_Supervisor::BrakeFacts) -> bool
{
  ((api_brake_observation == Vehicle_Start_Readiness_Recovery_Supervisor::BrakeObservation::Pressed) &
    api_brake_to_authorization.evidenceTrusted &
    api_brake_to_authorization.readyForAdmission |
    (api_brake_observation == Vehicle_Start_Readiness_Recovery_Supervisor::BrakeObservation::Released) &
      api_brake_to_authorization.evidenceTrusted &
      (api_brake_to_authorization.readyForAdmission == false) |
    (api_brake_observation == Vehicle_Start_Readiness_Recovery_Supervisor::BrakeObservation::Invalid) &
      (api_brake_to_authorization.evidenceTrusted == false) &
      (api_brake_to_authorization.readyForAdmission == false)) &
    (api_brake_to_lifecycle.evidenceTrusted == api_brake_to_authorization.evidenceTrusted) &
    (api_brake_to_lifecycle.readyForAdmission == api_brake_to_authorization.readyForAdmission)
}

